<?php declare(strict_types=1); namespace Annam; $title='Order '.$order['order_no']; $base='/checkout/complete/'.$reference.'/';$state=(new CustomerReceipt($store))->state($order,$reference); ?>
<section class="wrap php-store-section php-checkout-flow php-received-page"><div class="page-intro"><p class="section-kicker">Order received</p><h1>Thank you, <?= e($order['address']['recipient_name']??'') ?>.</h1><p>Your order is with the kitchen. Keep this page for your order details.</p></div>
<div class="checkout-layout"><section class="checkout-card"><p class="checkout-step">Order reference</p><h2><?= e($order['order_no']) ?></h2><p><span data-order-status><?= e($state['order_label']) ?></span> · <strong data-payment-status><?= e($state['payment_label']) ?></strong></p>
<?php if(!empty($order['delivery_date'])):?><p class="checkout-note"><?= e(implode(' + ',array_unique(array_map(fn($line)=>ucfirst($line['meal_key']??'Shop'),$order['items'])))) ?> · <?= e(date('l, j F Y',strtotime($order['delivery_date']))) ?></p><?php endif;?><?php $checkoutLines=$order['items'];require __DIR__.'/checkout-lines.php'; ?><div class="checkout-address"><h3>Delivery address</h3><p><?= e($order['address']['line1']??'') ?><?php if($order['address']['line2']??''):?><br><?= e($order['address']['line2']) ?><?php endif;?><br><?= e(($order['address']['city']??'').' · '.($order['address']['pincode']??'')) ?><br><?= e(($order['address']['state']??'').' · '.($order['address']['country']??'')) ?><?php if($order['address']['landmark']??''):?><br>Landmark: <?= e($order['address']['landmark']) ?><?php endif;?></p><p><?= e($order['address']['phone']??'') ?></p></div></section>
<aside class="checkout-card"><h2>Order total</h2><div class="totals"><div><span>Items</span><span><?= money($order['subtotal']) ?></span></div><div><span>Delivery charge</span><span><?= !empty($order['address']['courier_deferred'])?'Pay separately after dispatch':money($order['delivery_fee']) ?></span></div><?php $adjustment=Money::parse($order['total'])-Money::parse($order['subtotal'])-Money::parse($order['delivery_fee']);if($adjustment):?><div><span>Tax, discounts &amp; rounding</span><span>₹<?= e(Money::signedDecimal($adjustment)) ?></span></div><?php endif;?><div class="grand"><span>Total</span><span><?= money($order['total']) ?></span></div></div>
<?php if(!$state['paid']&&$order['status']!=='cancelled'&&$order['payment_status']!=='refunded'):?><div data-payment-prompts><h3>Payment is awaiting confirmation</h3><p class="checkout-note"><?= $intent?'Complete your online payment below. Payment is confirmed only after verification.':nl2br(e($store->config['checkout_settings']['payment_instructions']??'The kitchen will contact you to arrange payment. Your order remains unpaid until the kitchen confirms receipt.')) ?></p></div><?php endif;?>
<section aria-label="Invoice and receipt" data-receipt data-status-url="<?= e($base.'updates/') ?>" data-reference="<?= e($reference) ?>"><h3>Your receipt</h3><p data-receipt-message><?= $state['paid']?'Payment received. Your receipt will appear here.':'Payment confirmation is pending.' ?></p><div class="receipt-actions"><a class="btn" data-invoice-view <?= $state['invoice_url']?'href="'.e($state['invoice_url']).'"':'hidden' ?>>View invoice</a><a class="btn btn-primary" data-invoice-download <?= $state['download_url']?'href="'.e($state['download_url']).'"':'hidden' ?> download><?= $state['test']?'Download TEST receipt PDF':'Download invoice PDF' ?></a></div><div class="receipt-actions" data-summary-actions <?= $state['invoice_url']||$state['download_url']?'hidden':'' ?>><a class="btn" href="<?= e($base.'summary/') ?>" target="_blank" rel="noopener">View order summary</a><a class="btn btn-primary" data-order-summary href="<?= e($base.'summary/download/') ?>" download>Download order summary PDF</a></div></section><script src="<?= e(asset_url('receipt.js')) ?>" defer></script>
<?php if($state['test']): ?><p class="strip strip-warn">TEST / SIMULATED PAYMENT — NOT AN INVOICE</p><?php endif; ?>
<?php if($order['payment_status']==='refunded'): ?><p>Payment refunded. Contact the kitchen for help.</p><?php elseif($order['status']==='cancelled'): ?><p>Order cancelled. Contact the kitchen about any payment already made.</p><?php elseif(!$state['paid']&&$intent): ?><div data-payment-prompts>
<?php if($intent['provider_order_id']): ?><button class="btn btn-primary" id="pay-online" data-options="<?= e(json_encode(['key'=>$intent['key_id'],'order_id'=>$intent['provider_order_id'],'amount'=>(int)$intent['amount'],'currency'=>'INR','name'=>$store->name(),'prefill'=>['name'=>$order['address']['recipient_name']??'','contact'=>$order['address']['phone']??'']])) ?>">Pay <?= money($order['total']) ?></button><form id="payment-verify" method="post" action="<?= e($base.'verify/') ?>"><?= csrf() ?><?php foreach(['razorpay_payment_id','razorpay_order_id','razorpay_signature'] as $key): ?><input type="hidden" name="<?= e($key) ?>"><?php endforeach; ?></form><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><script src="<?= e(asset_url('payment.js')) ?>" defer></script>
<?php else: ?><form method="post" action="<?= e($base.'pay/') ?>"><?= csrf() ?><button class="btn btn-primary">Retry payment setup</button></form><?php endif; ?><form method="post" action="<?= e($base.'status/') ?>"><?= csrf() ?><button class="btn">Check payment status</button></form><p role="status" data-payment-feedback></p></div>
<?php endif; ?><?php if($website->whatsapp()):?><p class="receipt-contact"><a class="btn btn-wa" href="<?= e($website->whatsapp()) ?>" target="_blank" rel="noopener">Contact the kitchen</a></p><?php endif;?><p class="receipt-return"><a class="checkout-back" href="/">Back to the website →</a></p></aside></div></section>
<?php if($charge??null): ?><section class="wrap php-white"><h2>Courier delivery</h2><p><?= e(Delivery::COURIER) ?></p><?php if($charge['dispatched_at']): ?><p><?= e($charge['courier_name'].' · '.$charge['tracking_number']) ?></p><p>Courier charge: <?= money($charge['amount']) ?> · <?= $charge['paid_at']?'Paid separately':'Payable separately' ?></p><?php if(!$charge['paid_at']&&getenv('PAYMENTS_ENABLED')==='1'&&!empty($store->config['checkout_settings']['courier_online_enabled'])): ?><?php if($courierIntent['provider_order_id']??''): ?><button class="btn btn-primary" id="pay-courier" data-options="<?= e(json_encode(['key'=>$courierIntent['key_id'],'order_id'=>$courierIntent['provider_order_id'],'amount'=>(int)$courierIntent['amount'],'currency'=>'INR','name'=>$store->name()])) ?>">Pay courier charge</button><form id="courier-verify" method="post" action="<?= e($base.'courier-verify/') ?>"><?= csrf() ?><?php foreach(['razorpay_payment_id','razorpay_order_id','razorpay_signature'] as $k): ?><input type="hidden" name="<?= e($k) ?>"><?php endforeach; ?></form><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><script src="<?= e(asset_url('courier-payment.js')) ?>" defer></script><?php else: ?><form method="post" action="<?= e($base.'courier-pay/') ?>"><?= csrf() ?><button class="btn btn-primary">Pay separate courier charge</button></form><?php endif; endif; endif; ?></section><?php endif; ?>